// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

contract InvMutTest is Test {
    PuttyV2 c;

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(address to, uint256 nonce) public {
        vm.assume(to != address(0) && to != address(this));

        FakeToken token = new FakeToken();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 1,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(65);

        c.fillOrder(order, sig, floorAssetTokenIds);

        uint256 longId = uint256(c.hashOrder(order));
        require(c.ownerOf(longId) == address(this), "setup: not minted");

        vm.prank(address(this));
        bool ok;
        try c.transferFrom(address(this), to, longId) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: any successful transferFrom must transfer ownership:
        // after transferFrom(from, to, id) succeeds, ownerOf(id) == to.
        assertTrue(ok && c.ownerOf(longId) == to, "ownership must transfer");
    }
}
